import json,pathlib
r=pathlib.Path(__file__).parent
items=[('CL_PROP_0001','青铜油灯',['unlit','lit','damaged'],'铜锭+灯芯+灯油'),('CL_PROP_0002','酒坛',['sealed','open','broken'],'陶土+窑烧+酒'),('CL_PROP_0003','木桶',['empty','filled','broken'],'木板+铁箍'),('CL_PROP_0004','木箱',['closed','open','broken'],'木板+铁钉'),('CL_PROP_0005','木桌',['intact','damaged'],'木板+木榫'),('CL_PROP_0006','木椅',['intact','damaged'],'木材+木榫'),('CL_PROP_0007','货架',['stocked','empty'],'木板+木榫'),('CL_PROP_0008','摊位',['open','closed'],'木材+布匹'),('CL_PROP_0009','伞架',['stocked','empty'],'竹材+木材'),('CL_PROP_0010','路灯',['lit','unlit','damaged'],'木材+灯笼'),('CL_PROP_0011','石井',['intact','dry','broken'],'石材+绳索'),('CL_PROP_0012','水缸',['intact','broken'],'陶土+窑烧'),('CL_PROP_0013','石磨',['intact','broken'],'石材+木柄'),('CL_PROP_0014','柴堆',['full','small'],'木材'),('CL_PROP_0015','稻草堆',['full','scattered'],'稻草'),('CL_PROP_0016','桃树',['spring','summer','autumn','winter'],'桃核+土壤+水+时间'),('CL_PROP_0017','花丛',['pink','white','purple'],'种子+土壤+水+时间'),('CL_PROP_0018','岩石',['granite','mossy'],'自然生成/采矿'),('CL_PROP_0019','草药',['young','mature','harvested'],'药草种子+土壤+水+时间'),('CL_PROP_0020','栅栏',['intact','broken'],'木材+木榫')]
style='premium Chinese xianxia game item, consistent hand-painted isometric 3/4 view, finely detailed physically coherent material, full object visible, centered, single isolated object, no labels, no text, no panels, soft ambient lighting, transparent background if supported'
jobs=[];recipes=[]
for id,name,states,recipe in items:
 recipes.append({'id':id,'name':name,'production_rule':recipe,'spawn_policy':'craft_or_world_simulation_only','note':'recipe expression is design draft, not implemented gameplay'})
 for state in states:jobs.append({'id':id,'name':name,'state':state,'prompt_node':'6','prompt':f'{style}. Item: {name}. State: {state}. Same canonical silhouette across variants.'})
(r/'jobs.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2));(r/'recipes_draft.json').write_text(json.dumps(recipes,ensure_ascii=False,indent=2));print(len(items),len(jobs))
